module top_pad (
	clk, 
	rst, 
	sclk, 
	cs_n, 
	mosi, 
	miso);
   input clk;
   input rst;
   input sclk;
   input cs_n;
   input mosi;
   output miso;

   // Internal wires
   wire clk_PAD;
   wire cs_n_PAD;
   wire miso_PAD;
   wire mosi_PAD;
   wire rst_PAD;
   wire sclk_PAD;

   TopModule core (.clk(clk_PAD),
	.rst(rst_PAD),
	.sclk(sclk_PAD),
	.cs_n(cs_n_PAD),
	.mosi(mosi_PAD),
	.miso(miso_PAD));
   pad_corner corner0 ();
   pad_corner corner1 ();
   pad_corner corner2 ();
   pad_corner corner3 ();
   pad_vdd vdd0 ();
   pad_gnd vss0 ();
   pad_in clk_pad (.DataIn(clk_PAD),
	.pad(clk));
   pad_in cs_n_pad (.DataIn(cs_n_PAD),
	.pad(cs_n));
   pad_out miso_pad (.pad(miso),
	.DataOut(miso_PAD));
   pad_in mosi_pad (.DataIn(mosi_PAD),
	.pad(mosi));
   pad_in rst_pad (.DataIn(rst_PAD),
	.pad(rst));
   pad_in sclk_pad (.DataIn(sclk_PAD),
	.pad(sclk));
endmodule

